def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        grid[x][y] = value
    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    def max_sum(x, y, direction):
        if direction == 0:
            if x >= N or y >= N or x < 0 or y < 0:
                return float('-inf')
            if dp[x][y][0] != 0:
                return dp[x][y][0]
            t1 = max_sum(x + 1, y + 1, 0) + grid[x][y]
            t2 = max_sum(x + 1, y, 0) + grid[x][y]
            dp[x][y][0] = max(t1, t2)
            return dp[x][y][0]
        elif direction == 1:
            if y >= N or x >= N or x < 0 or y < 0:
                return float('-inf')
            if dp[x][y][1] != 0:
                return dp[x][y][1]
            t1 = max_sum(x + 1, y + 1, 1) + grid[x][y]
            t2 = max_sum(x, y + 1, 1) + grid[x][y]
            dp[x][y][1] = max(t1, t2)
            return dp[x][y][1]
        else:
            raise ValueError("Invalid direction")

    max_path1 = float('-inf')
    max_path2 = float('-inf')
    for i in range(N):
        if dp[i][0][0] + dp[i][N-1][1] > max_path1 + max_path2:
            max_path1, max_path2 = dp[i][0][0] + dp[i][N-1][1], max_path1
        if dp[i][0][1] + dp[i][N-1][0] > max_path1 + max_path2:
            max_path1, max_path2 = dp[i][0][1] + dp[i][N-1][0], max_path1
        if dp[i][N-1][1] + dp[i+1][0] > max_path1 + max_path2:
            max_path1, max_path2 = dp[i][N-1][1] + dp[i+1][0], max_path1
        if dp[i][N-1][0] + dp[i+1][1] > max_path1 + max_path2:
            max_path1, max_path2 = dp[i][N-1][0] + dp[i+1][1], max_path1

    return max_path1 + max_path2

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    def max_sum_from(lst):
        if not lst:
            return 0
        max_val = lst[0]
        for val in lst[1:]:
            max_val = max(max_val, val)
        return max_val

    Jennings = [[0 for _ in range(N)] for _ in range(N)]
    Jennings[0][0] = grid_values[0][2]
    pointers = [[(0, 0)]]

    for _ in range(N**2 - len(grid_values) - 2):
        new_pointers = []
        for pre_pointer in pointers:
            x, y = pre_pointer[-1]
            for nx, ny in [(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)]:
                if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in pre_pointer:
                    new_pointers.append((nx, ny))
                    Jennings[nx][ny] = max(Jennings[nx][ny], Jennings[x][y] + grid_values[grid_values.index((nx, ny, 0))][2])

        pointers = new_pointers

    Jennings[N - 1][N - 1] += max_sum_from(Jennings[N][N - 1:])
    Jennings[N - 1][N - 1] += max_sum_from(Jennings[N - 1][N - 1:])
    Jennings[N - 1][N - 1] = max(Jennings[N - 1][N - 1], Jennings[N - 2][N - 1:])
    Jennings[N - 1][N - 1] = max(Jennings[N - 1][N - 1], Jennings[N - 2][N - 2])

    return Jennings[N - 1][N - 1]

