def cantor_numbering(N: int) -> str:
    if N == 0:
        return "0/1"

    a, b = N, 0
    while a > 0:
        if a % 2 == 0:
            a //= 2
            b += 1
        else:
            a = (a + 1) // 2
            b *= 2

    return f"{b}/{a}"

