        return "1/1"
    else:
        part = N % 2
        step = (N - 1) // 2
        if part == 1:
            return convert_step(step) + '/' + str(2 * step + 2)
        else:
            return str(2 * step + 2) + '/' + convert_step(step + 1)

def convert_step(step):
