def max_product(num_str: str, N: int, K: int) -> int:
    num_list = [int(digit) for digit in num_str]
    dp = [[0 for _ in range(K + 1)] for _ in range(N + 1)]

    for i in range(1, N + 1):
        for j in range(1, K + 1):
            for l in range(i):
                dp[i][j] = max(dp[i][j], dp[l][j - 1] * num_list[l] * num_list[i - l - 1])

    return dp[N][K]

def max_product(num_str, N, K):
    def generate_combinations(arr, K):
        from itertools import combinations_with_replacement
        return list(combinations_with_replacement(arr, K))

    def evaluate_combination(combination):
        return int(''.join(combination))

    def find_max_product(nums_list):
        max_product = float('-inf')
        for combination in nums_list:
            product = evaluate_combination(combination)
            max_product = max(max_product, product)
        return max_product

    # Step 1: Generate all possible combinations of K multiplication signs
    values = [int(digit) for digit in num_str]
    indices = list(range(N))
    combinations = generate_combinations(indices, K)

    # Step 2: Evaluate the product of each combination
    combinations_product = []
    for combination in combinations:
        val = ''.join([str(values[i]) for i in combination])
        combinations_product.append(val)

    # Step 3: Find the maximum product
    result = find_max_product(combinations_product)
    return result

