        return 1
    if m % 2 == 1 or n % 2 == 1:
        return 0
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][1] = i - 1
    for i in range(2, m + 1):
        for j in range(2, n + 1):
            dp[j][i] = (dp[j][i-1] + dp[j-1][i-1]) % 1000000007
    return dp[n][m]

def count_passing_ways(n, m):
