        return 0
    if m == 0:
        return 1

    dp = [[0] * m for _ in range(n)]

    # Base case: the ball is in the first position and returns to the first position after one pass
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n):
        for j in range(m):
            # From the left neighbor
            if i > 0:
                dp[i][j] += dp[i-1][j] % 1000000007
            # From the right neighbor
            if i < n-1:
                dp[i][j] += dp[i+1][j] % 1000000007

    return dp[n-1][m-1]

