def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    def format_coefficient(coeff: int):
        if coeff == 0:
            return ''
        sign = '-' if coeff < 0 else '+'
        magnitude = abs(coeff)
        if magnitude == 1:
            return sign + 'x' if sign else ''  # Handle constant term as only x^0 or just x
        elif magnitude == coeffs[-1]:
            return sign + f'x^{magnitude - 1}'  # Handle constant term as only x^0 or just x
        else:
            return sign + f'{magnitude}x^{magnitude - 1}'

    result = []
    for i, coeff in enumerate(coeffs, start=1):
        if coeff != 0:
            result.append(format_coefficient(coeff))
            if i < n:
                result.append('-' if i != n else '')
    return ''.join(result)

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    series = []
    for i in range(n, -1, -1):
        # Skip terms with a coefficient of zero
        if coeffs[i] == 0:
            continue
        # Determine the term's sign and format the coefficient
        coefficient = abs(coeffs[i])
        sign = '+' if coeff > 0 else '-'
        if sign == '+':
            if coeff == 1 and i != 0:
                coefficient = 'x'
            elif coeff == 1 and i == 0 and n == 1:
                coefficient = ''
            elif coeff == 1 and i == 0 and n > 1:
                coefficient = 'x^0'
            else:
                coefficient = f'{coefficient}x^{i}'
        else:
            if i == 1 and n == 1:
                coefficient = 'x'
            elif i == 1:
                coefficient = '-x'
            else:
                coefficient = f'-{coefficient}x^{i}'
        # Add the term to the series
        series.append(f'{sign}{coefficient}')
    # Join the series into a single string
    return ' + '.join(series)

