        if n < 0:
            return 0
        count = 0
        for i in range(start, n//x + 1):
            count += generate_partitions(n - i * x, k - 1, x, i)
        return count

    # Compute the sum of all partitions
    return sum(generate_partitions(n, k, x, i) for i in range(x, n//x + 1))

