def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a 2D array dp where dp[i][j] represents the maximum volume that can be occupied
    # by the first i items with a subset of the first j volumes
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill dp table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            if volumes[j - 1] <= i:
                dp[i][j] = max(dp[i][j - 1], dp[i - volumes[j - 1]][j - 1] + volumes[j - 1])
            else:
                dp[i][j] = dp[i][j - 1]

    # The minimum remaining space is the difference between the box's total capacity and the maximum occupied volume
    return V - dp[V][n]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [0] * (V + 1)
    for volume in volumes:
        for i in range(V, volume - 1, -1):
            dp[i] = max(dp[i], dp[i - volume] + volume)
    return V - dp[V]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Assuming volumes is sorted in descending order
    volumes.sort(reverse=True)

    # Dictionary to store the maximum capacity of each item up to the index i
    max_capacity = [0] * (n + 1)

    for i in range(1, n + 1):
        max_capacity[i] = max_capacity[i - 1]
        for j in range(i):
            if max_capacity[j] + volumes[i - 1] <= V:
                max_capacity[i] = max(max_capacity[i], max_capacity[j] + volumes[i - 1])
        # If adding the item at index i exceeds the box capacity, no more items can be added
        if max_capacity[i] > V:
            break

    # The minimum remaining space is the difference between the box capacity and the maximum occupied volume
    min_space = V - max_capacity[n]
    return min_space

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    max_occupied_capacity = 0
    for i in range(1 << n):
        occupied_capacity = sum(volumes[j] for j in range(n) if i & (1 << j))
        if occupied_capacity > max_occupied_capacity:
            max_occupied_capacity = occupied_capacity
    return V - max_occupied_capacity

