def vigenere_decrypt(key: str, ciphertext: str) -> str:
    # Convert key and ciphertext to uppercase
    key = key.upper()
    ciphertext = ciphertext.upper()

    # Determine the length of the key
    key_length = len(key)

    #.Replace spaces in the key and ciphertext with the first letter of the key
    key = key.replace(" ", key[0])
    ciphertext = ciphertext.replace(" ", key[0])

    # Create a mapping from each lowercase alphabetic character to its corresponding index
    def char_to_index(char):
        return ord(char) - ord('A')

    # Create a mapping from each index to its corresponding lowercase alphabetic character
    def index_to_char(index):
        return chr(index + ord('A'))

    # Perform the Vigenère decryption
    decrypted = ""
    for i, char in enumerate(ciphertext):
        if char.isalpha():
            index = char_to_index(char)
            shift = char_to_index(key[i % key_length])
            decrypted += index_to_char((index - shift + 26) % 26)
        else:
            decrypted += char

    return decrypted

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    # Ensure the key is a single uppercase character
    if len(key) != 1 or not key.isalpha():
        raise ValueError("Key should be a single uppercase character.")

    # Ensure the ciphertext is alphabetic
    if not ciphertext.isalpha():
        raise ValueError("Ciphertext should consist only of alphabetic characters.")

    # Create a map of each character in the alphabet to its encrypted counterpart
    enc_map = {}
    key_index = 0
    for char in ciphertext:
        lower_char = char.lower()
        original_char = lower_char + key.lower()
        if original_char in enc_map:
            enc_map[char] = enc_map[original_char]
        else:
            enc_map[char] = ord(lower_char) - ord('a') + ord(key.lower()) - ord('a')

    # Decode the ciphertext using the encryption map
    plaintext = ''
    for char in ciphertext:
        filtered_char = enc_map.get(char, char)  # Automatically handles charactersnot in the encryption map
        plaintext += filtered_char

    # Convert the output back to uppercase and return
    return plaintext.upper()

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_letter(char, shift):
        if char.islower():
            return chr((ord('a') + (ord(char) - ord('a') + shift) % 26))
        elif char.isupper():
            return chr((ord('A') + (ord(char) - ord('A') + shift) % 26))
        return char

    plaintext = ""
    for i, char in enumerate(ciphertext):
        key_char = key[i % len(key)]
        shift = ord(key_char) - ord('a')
        plaintext += shift_letter(char, -shift)
    return plaintext

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    # Validate key
    if not key.isalpha():
        raise ValueError("Key must only contain alphabetic characters")

    # Validate ciphertext
    if not ciphertext.isalpha():
        raise ValueError("Ciphertext must only contain alphabetic characters")

    # Create a Caesar map for each letter of key
    caesar_map = {letter: (ord(letter.lower()) - ord('a') - ord(key[i % len(key)].lower()) % 26 + ord('a')) for i, letter in enumerate(key.lower())}

    # Apply the Caesar decryption to each character in the ciphertext
    decrypted = ''.join([chr(caesar_map[c]) for c in ciphertext.lower()])

    return decrypted.upper()

