def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14
    else:
        # Recursive formula for hanoi_double_iterative(n):
        # hanoi_double_iterative(n) = 2 * hanoi_double_iterative(n - 1) + 2 * (hanoi_double_iterative(n - 2) + 1)
        def helper(n):
            if n == 1:
                return 2
            elif n == 2:
                return 6
            elif n == 3:
                return 14
            else:
                # Recursion
                return 2 * helper(n - 1) + 2 * (helper(n - 2) + 1)

        # Call the helper function with the input value
        return helper(n)

