def hanoi_double_iterative(n: int) -> int:
    # Known recursive relation for n_pairs
    def double_hanoi(n):
        if n == 0:
            return 0
        elif n == 1:
            return 2
        else:
            return 2 * double_hanoi(n - 1) + 4

    # Calculate the total number of moves for double_hanoi(n_pairs)
    total_moves = double_hanoi(n)
    return total_moves

